  ('1a659bb3-8a75-4c3e-a8fb-3e43e6089f15', '44879d8c-59bb-4c5b-aa2a-6d346997816d', 1022, 'bdf8b579-22a3-4090-8ecc-29ca330f149d', 'abfluss-verstopft', 'Abfluss im Bad läuft nicht ab', 'Sanitär – Entwässerung', 'sanitaer'::gewerk, 'dringend'::prioritaet, 'erledigt'::vorgang_status, 'Waschbecken im Bad läuft nicht ab, Dusche und WC unauffällig. Kunststoff-Flaschensiphon, frei zugänglich. Einzelverstopfung wahrscheinlich, kein Strangproblem.', 'whatsapp'::kanal, '3cf3b070-0bce-4010-86e9-7ce278110814', '022a1de0-dc38-4d87-96b2-60a265463988', now() + interval '-3031200 seconds', true, 85, false, false, true, now() + interval '-3204000 seconds', now() + interval '-3142800 seconds'),
  ('fe0f07b8-cb25-4f21-86d2-16110be1c9a6', '44879d8c-59bb-4c5b-aa2a-6d346997816d', 1023, 'b9127c93-ad29-40f5-9c36-24198bc172e8', 'wasserhahn-tropft', 'Tropfender Wasserhahn in der Küche', 'Sanitär – Armatur', 'sanitaer'::gewerk, 'routine'::prioritaet, 'erledigt'::vorgang_status, 'Einhebelmischer in der Küche tropft am Auslauf, verschlissene Kartusche (35 mm). Eckventile unter der Spüle vorhanden und gängig. Reparatur in einem Termin ohne Absperrung des Hausanschlusses möglich.', 'whatsapp'::kanal, '3cf3b070-0bce-4010-86e9-7ce278110814', '022a1de0-dc38-4d87-96b2-60a265463988', now() + interval '-3024000 seconds', true, 95, false, false, true, now() + interval '-3456000 seconds', now() + interval '-3160800 seconds'),
