  ('d1901167-2b17-4de3-9371-53a385b9580c', '44879d8c-59bb-4c5b-aa2a-6d346997816d', '22951ced-e91f-4977-9629-82438ebbf100', '8dad1be3-a0d3-4edc-8d70-0878681f11a1', null, 'mieter'::nachricht_richtung, 'whatsapp'::kanal, 'Guten Tag, ich möchte einen Schaden melden.', null, null, true, now() + interval '-7200 seconds', now() + interval '-7140 seconds'),
  ('6afca4f4-2162-4021-8378-e11ab4353ee6', '44879d8c-59bb-4c5b-aa2a-6d346997816d', '22951ced-e91f-4977-9629-82438ebbf100', '8dad1be3-a0d3-4edc-8d70-0878681f11a1', null, 'mieter'::nachricht_richtung, 'whatsapp'::kanal, '[Foto]', 'wasserfleck-decke.jpg', null, true, now() + interval '-7140 seconds', now() + interval '-7080 seconds'),
  ('415fc4f9-243e-44c1-b689-ec2edd99edc8', '44879d8c-59bb-4c5b-aa2a-6d346997816d', '22951ced-e91f-4977-9629-82438ebbf100', '8dad1be3-a0d3-4edc-8d70-0878681f11a1', null, 'ki'::nachricht_richtung, 'whatsapp'::kanal, 'Das sieht nach einem aktiven Wasserschaden aus: ein feuchter, durchgedrückter Fleck an der Decke mit deutlicher Randbildung. Das ist kein alter Schaden. Ich stufe das als Notfall ein und leite es sofort weiter.', null, null, true, now() + interval '-7080 seconds', now() + interval '-7020 seconds'),
  ('54d1eb39-f82c-4287-84fc-9c79747b4210', '44879d8c-59bb-4c5b-aa2a-6d346997816d', '22951ced-e91f-4977-9629-82438ebbf100', '8dad1be3-a0d3-4edc-8d70-0878681f11a1', null, 'mieter'::nachricht_richtung, 'whatsapp'::kanal, 'Ja, das stimmt.', null, null, true, now() + interval '-7020 seconds', now() + interval '-6960 seconds'),
  ('5c647f15-1134-4ad2-9df5-56f25b91390f', '44879d8c-59bb-4c5b-aa2a-6d346997816d', '22951ced-e91f-4977-9629-82438ebbf100', '8dad1be3-a0d3-4edc-8d70-0878681f11a1', null, 'ki'::nachricht_richtung, 'whatsapp'::kanal, 'Bitte tun Sie jetzt sofort zwei Dinge: Stellen Sie einen Eimer unter die Stelle und schalten Sie in dem Raum die Sicherung für Licht und Steckdosen aus. Betreten Sie den Bereich nicht, falls sich die Decke sichtbar durchbiegt.', null, '{"art":"sofortmassnahme"}'::jsonb, true, now() + interval '-6960 seconds', now() + interval '-6900 seconds'),
  ('8ca0b92a-c459-4113-9d0d-fb898abce487', '44879d8c-59bb-4c5b-aa2a-6d346997816d', '22951ced-e91f-4977-9629-82438ebbf100', '8dad1be3-a0d3-4edc-8d70-0878681f11a1', null, 'ki'::nachricht_richtung, 'whatsapp'::kanal, 'Der Notdienst ist unterwegs, darauf müssen Sie nicht warten. Während er fährt, hilft mir ein Foto aus etwas größerem Abstand sehr: Ich möchte sehen, wo im Raum der Fleck sitzt – davon hängt ab, ob er gleich Zugang zur Wohnung darüber braucht.', null, null, true, now() + interval '-6900 seconds', now() + interval '-6840 seconds'),
  ('f319ec2a-fe83-4060-9107-25156e7225b5', '44879d8c-59bb-4c5b-aa2a-6d346997816d', '22951ced-e91f-4977-9629-82438ebbf100', '8dad1be3-a0d3-4edc-8d70-0878681f11a1', null, 'mieter'::nachricht_richtung, 'whatsapp'::kanal, '[Foto]', 'wasserfleck-weit.jpg', null, true, now() + interval '-6780 seconds', now() + interval '-6720 seconds'),
  ('2249cd08-222a-4e1a-bfba-de09d0c34b6f', '44879d8c-59bb-4c5b-aa2a-6d346997816d', '22951ced-e91f-4977-9629-82438ebbf100', '8dad1be3-a0d3-4edc-8d70-0878681f11a1', null, 'ki'::nachricht_richtung, 'whatsapp'::kanal, 'Der Fleck sitzt direkt unterhalb des Badezimmers der darüberliegenden Wohnung und misst etwa 60 mal 40 Zentimeter. Damit ist die Ursache sehr wahrscheinlich eine undichte Leitung oder Abdichtung in der Wohnung darüber. Der Notdienst weiß dadurch, dass er Zugang zu beiden Wohnungen braucht – das erspart eine zweite Anfahrt.', null, null, true, now() + interval '-6720 seconds', now() + interval '-6660 seconds'),
  ('21748c9d-8c1c-4335-84a3-50af8249b99a', '44879d8c-59bb-4c5b-aa2a-6d346997816d', '22951ced-e91f-4977-9629-82438ebbf100', '8dad1be3-a0d3-4edc-8d70-0878681f11a1', null, 'ki'::nachricht_richtung, 'whatsapp'::kanal, 'Das erspart dem Betrieb voraussichtlich eine zweite Anfahrt.', null, '{"art":"erkenntnis","vorher":"Wasserschaden gemeldet, Ursache und Zugangsbedarf unklar","nachher":"Ursache in der Wohnung darüber – Notdienst organisiert beide Zugänge"}'::jsonb, true, now() + interval '-6660 seconds', now() + interval '-6600 seconds'),
