-- ---------------------------------------------------------------------------
-- Beispieldaten: Muster Hausverwaltung GmbH
--
-- ERZEUGT – NICHT VON HAND BEARBEITEN.
-- Quelle: config/muster-mandant.ts, config/scenarios.ts
-- Neu erzeugen mit:  npm run seed:sql
--
-- Einspielen:
--   Kommandozeile   npx supabase db push  (Migrationen)  und diese Datei
--   ohne Terminal   Inhalt kopieren und im Supabase SQL Editor ausführen
--
-- Die Datei ist wiederholbar: Sie leert die Bewegungsdaten des Mandanten und
-- schreibt sie neu. Ein zweiter Durchlauf stellt also den Ausgangszustand
-- wieder her – genau das, was der Zurücksetzen-Knopf tut.
--
-- Zeitangaben sind relativ zu now(), die Datei veraltet daher nicht.
-- ---------------------------------------------------------------------------

begin;

-- Mandant anlegen oder aktualisieren
  id, slug, firma, logo_url, primaerfarbe, sekundaerfarbe, ansprechpartner,
  stadt, objekt_namen, mitarbeiter, handwerker, einstellungen,
  ablaufdatum, aufrufe, ist_aktiv, erstellt_am
) values (
  '44879d8c-59bb-4c5b-aa2a-6d346997816d', 'muster', 'Muster Hausverwaltung GmbH', null,
  '#1F4E79', '#2F7D8C', 'Herr Peter Muster',
  'Kassel', array['Wilhelmshöher Allee 112', 'Holländische Straße 47', 'Ludwig-Mond-Straße 8', 'Germaniastraße 23']::text[], '[{"name":"Andrea Wilke","rolle":"Objektbetreuung","bereich":"technik"},{"name":"Thomas Reinhardt","rolle":"Buchhaltung","bereich":"buchhaltung"},{"name":"Sabine Groß","rolle":"WEG-Verwaltung","bereich":"weg"},{"name":"Kevin Bartsch","rolle":"Assistenz","bereich":"allgemein"}]'::jsonb,
  '[{"firma":"Sanitär Krause GmbH","gewerk":"sanitaer","reaktionszeit_h":4,"bewertung":4.6,"ansprechpartner":"Frau Krause","kontaktKanal":"whatsapp","abstimmungErlaubt":true,"arbeitszeiten":"Mo–Do 7–16 Uhr, Fr 7–13 Uhr"},{"firma":"Heizungsbau Nolte","gewerk":"heizung","reaktionszeit_h":8,"bewertung":4.3,"ansprechpartner":"Herr Nolte","kontaktKanal":"email","abstimmungErlaubt":true,"arbeitszeiten":"Mo–Fr 8–17 Uhr"},{"firma":"Elektro Sander & Sohn","gewerk":"elektro","reaktionszeit_h":12,"bewertung":4.8,"ansprechpartner":"Herr Sander"},{"firma":"Malerbetrieb Ziegler","gewerk":"maler","reaktionszeit_h":48,"bewertung":4.1},{"firma":"Tischlerei Hanke","gewerk":"schreiner","reaktionszeit_h":36,"bewertung":4.5},{"firma":"Gebäudereinigung Vogt","gewerk":"reinigung","reaktionszeit_h":24,"bewertung":4},{"firma":"Schlüsseldienst Kassel 24","gewerk":"schluesseldienst","reaktionszeit_h":1,"bewertung":3.9}]'::jsonb, '{"sla_stunden":{"notfall":4,"dringend":48,"routine":120},"notfall_telefon":"0561 9000000","kleinreparatur_grenze_euro":100,"hinweis":"Demo-Konfiguration. Werte können jederzeit angepasst werden."}'::jsonb,
  null, 0, true, now() + interval '-2592000 seconds'
)
on conflict (id) do update set
  firma = excluded.firma,
  primaerfarbe = excluded.primaerfarbe,
  sekundaerfarbe = excluded.sekundaerfarbe,
  ansprechpartner = excluded.ansprechpartner,
  stadt = excluded.stadt,
  objekt_namen = excluded.objekt_namen,
  mitarbeiter = excluded.mitarbeiter,
  handwerker = excluded.handwerker,
  einstellungen = excluded.einstellungen,
  ist_aktiv = excluded.ist_aktiv;

-- Bewegungsdaten leeren, damit ein erneuter Lauf sauber aufsetzt
select demo_leeren('muster');










